 38			}
 39	
 40			for _, f := range flags {
 41				flag := &Flag{
 42					Key:         f.Key,
 43					Name:        f.Name,
 44					Description: f.Description,
 45					Enabled:     f.Enabled,
 46				}
 47	
 48				variantKeys := make(map[string]string, len(f.Variants))
 49				for _, v := range f.Variants {
 50					variant := &Variant{
 51						Key:         v.Key,
 52						Name:        v.Name,
 53						Description: v.Description,
