155	// convert replaces YAML's interface{} map keys with strings at every depth.
156	func convert(value interface{}) interface{} {
157		switch value := value.(type) {
158		case map[interface{}]interface{}:
159			result := make(map[string]interface{}, len(value))
160			for key, item := range value {
161				result[fmt.Sprint(key)] = convert(item)
162			}
163			return result
164		case map[string]interface{}:
165			result := make(map[string]interface{}, len(value))
166			for key, item := range value {
167				result[key] = convert(item)
168			}
169			return result
170		case []interface{}:
171			result := make([]interface{}, len(value))
172			for index, item := range value {
173				result[index] = convert(item)
174			}
175			return result
176		default:
177			return value
178		}
179	}
